#!/usr/bin/env python3
"""record (PostToolUse Skill): log review-skill runs per session. gate (PreToolUse Bash): block
`gh pr create|edit` bodies that tick a review box with no run since the head commit / /create-pr."""
import json
import os
import re
import subprocess
import sys
import time
from datetime import datetime
from pathlib import Path



def dgflow_setting(key: str, default: str) -> str:
    # Same precedence as scripts/lib/config.sh: env var, then ~/.claude/dgflow.env, then default.
    if os.environ.get(key):
        return os.path.expanduser(os.environ[key])
    config = Path(os.environ.get("DGFLOW_CONFIG", Path.home() / ".claude" / "dgflow.env"))
    if config.is_file():
        for line in config.read_text().splitlines():
            name, _, value = line.partition("=")
            if name.strip() == key and value.strip():
                value = value.strip().strip("\"'").replace("$HOME", str(Path.home()))
                return os.path.expanduser(value)
    return os.path.expanduser(default)


STATE_DIR = Path(dgflow_setting("DGFLOW_STATE_DIR", "~/.claude/state/dgflow")) / "pr-receipts"
TRACKED = {"create-pr", "scope-check", "dg-pr-adherence-check", "dg-delegated-full-review"}
TICKED_BOX = {
    "scope-check": re.compile(r"-\s*\[[xX]\][^\n]*scope-check"),
    "dg-pr-adherence-check": re.compile(r"-\s*\[[xX]\][^\n]*dg-pr-adherence-check"),
    "dg-delegated-full-review": re.compile(
        r"-\s*\[[xX]\][^\n]*(dg-delegated-full-review|comprehensive review)"
    ),
}
PR_WRITE = re.compile(r"\bgh\s+pr\s+(create|edit)\b")


