mkdir -p hooks && cat > hooks/hooks.json <<'EOF'
{
  "description": "dgflow: PR review-receipt gate for create-pr, and a SessionEnd git-state safety net for checkpoint.",
  "hooks": {
    "PostToolUse": [
      {
        "matcher": "Skill",
        "hooks": [
          { "type": "command", "command": "python3 \"${CLAUDE_PLUGIN_ROOT}/scripts/pr-receipts.py\" record" }
        ]
      }
    ],
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          { "type": "command", "command": "python3 \"${CLAUDE_PLUGIN_ROOT}/scripts/pr-receipts.py\" gate", "timeout": 30 }
        ]
      }
    ],
    "SessionEnd": [
      {
        "hooks": [
          { "type": "command", "command": "bash \"${CLAUDE_PLUGIN_ROOT}/scripts/session-context.sh\" snapshot" }
        ]
      }
    ]
  }
}
EOF
python3 -m json.tool hooks/hooks.json >/dev/null && echo JSON_OK

